values ('bbbb0005-0000-4000-8000-000000000005', 'en', null, 'European History: 1450 to the Present', 'A survey of Europe from the Renaissance to the European Union, built for AP European History review. The sequence and factual backbone are adapted from OpenStax World History (CC BY 4.0), with every explanation rewritten as original prose. You will trace how humanism, revolution, industry, and two world wars reshaped the continent.', null, 'foundations', 45, true, 'humanities', '{}')
on conflict (id) do nothing;

insert into public.lessons (course_id, position, title, kind, body, grammar_notes_md, estimated_minutes)
select 'bbbb0005-0000-4000-8000-000000000005', v.pos, v.title, v.kind, v.body::jsonb, v.notes, v.mins
from (values
  (1, 'Diagnostic: where are you now?', 'quiz', '{"questions":[{"prompt":"Renaissance humanism is best described as a renewed interest in...","options":["the study of classical Greek and Roman texts and human potential","proving the earth is the center of the universe","abolishing private property","the divine right of kings"],"answer":0,"explanation":"Humanists revived ancient learning (the studia humanitatis) and emphasized human dignity and achievement, starting in Italy around 1400."},{"prompt":"Martin Luther''s 95 Theses, which sparked the Protestant Reformation, were posted in...","options":["1453","1492","1517","1648"],"answer":2,"explanation":"Luther challenged the sale of indulgences in 1517 at Wittenberg, opening the Reformation."},{"prompt":"Christopher Columbus first crossed the Atlantic for the Spanish crown in...","options":["1492","1498","1519","1588"],"answer":0,"explanation":"Columbus reached the Caribbean in 1492, opening sustained European contact with the Americas."},{"prompt":"Louis XIV of France is the classic example of a monarch who practiced...","options":["constitutional monarchy","absolutism","direct democracy","feudal decentralization"],"answer":1,"explanation":"Louis XIV (ruled 1643-1715) centralized power at Versailles and is associated with the claim that he was the state itself."},{"prompt":"Copernicus launched the Scientific Revolution by arguing that...","options":["the sun orbits the earth","the earth and planets orbit the sun","the earth is flat","comets cause plagues"],"answer":1,"explanation":"His 1543 heliocentric model placed the sun, not the earth, at the center, overturning the old system."},{"prompt":"The storming of the Bastille, a symbolic start of the French Revolution, occurred on July 14 of...","options":["1776","1789","1799","1815"],"answer":1,"explanation":"On July 14, 1789 a Paris crowd seized the Bastille fortress, and the date became France''s national holiday."},{"prompt":"The unification of Germany in 1871 was engineered mainly by...","options":["Giuseppe Garibaldi","Napoleon Bonaparte","Otto von Bismarck","Klemens von Metternich"],"answer":2,"explanation":"Bismarck, minister-president of Prussia, used diplomacy and war to proclaim the German Empire in 1871."},{"prompt":"World War II in Europe began when Germany invaded...","options":["France in 1940","Poland in 1939","the Soviet Union in 1941","Austria in 1938"],"answer":1,"explanation":"Germany''s invasion of Poland on September 1, 1939 triggered British and French declarations of war."}]}'::jsonb, null, 10),
  (2, 'The Renaissance and the humanist revival', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Explain what the Renaissance was, why it began in the Italian city-states, and how humanism changed how educated Europeans thought about themselves and the ancient world. You will be able to name key figures and connect the printing press to the spread of new ideas. Warm-up from the diagnostic: humanists were most excited about recovering which body of writing? If you answered the texts of ancient Greece and Rome, you already have the central thread of this lesson in hand, and the rest will build on it."},{"heading":"The idea","text":"The Renaissance, meaning rebirth, was a cultural movement running roughly from 1400 to 1600 that began in wealthy Italian cities such as Florence, Venice, and Rome. Trade and banking fortunes, especially those of families like the Medici, paid for art, architecture, and learning. At its core was humanism, a program of study built on classical Latin and Greek texts. Humanists like Petrarch believed that reading the ancients could teach people to live wisely and write beautifully. They prized individual achievement, civic life, and worldly accomplishment alongside religious faith. This was not a rejection of Christianity but a shift in emphasis toward human reason, talent, and the dignity of life on earth. Artists applied the same spirit, using perspective, anatomy, and classical models to portray people and nature with new realism."},{"heading":"Key events and causes","text":"The movement had deep causes. Italy''s independent, competitive city-states created patrons eager to display wealth and power through art. The fall of Constantinople to the Ottomans in 1453 pushed Greek scholars and manuscripts westward, enriching Italian libraries. Around 1440 Johannes Gutenberg developed movable-type printing in Mainz, and by 1500 printed books spread ideas faster and cheaper than ever, multiplying the humanists'' reach. The result was a cascade: Leonardo da Vinci, Michelangelo, and Raphael produced masterworks for popes and princes; Machiavelli analyzed power coldly in The Prince around 1513. Humanism then crossed the Alps. Northern humanists such as Erasmus, whose Praise of Folly appeared in 1509, and Thomas More, author of Utopia in 1516, applied classical learning to reform Christian life. Their push to return to original sources, including scripture, helped set the stage for the religious upheavals that followed."},{"heading":"Your turn","text":"1) Why did the Renaissance start in Italy rather than, say, England? 2) What does the word humanism point to? 3) How did Gutenberg''s press amplify Renaissance ideas? 4) Name one way northern humanism differed from the Italian version. 5) What event in 1453 helped bring Greek learning to Italy? Answers: 1) Rich, competitive city-states and banking wealth produced patrons for art and learning. 2) The study of classical texts and a focus on human reason, dignity, and achievement. 3) Printing made books cheaper and faster to copy, spreading humanist works widely. 4) Northern humanists like Erasmus aimed their classical skills at reforming Christianity and society. 5) The Ottoman conquest of Constantinople, which sent Greek scholars and manuscripts west."},{"heading":"Common mistakes and exit ticket","text":"Mistake: thinking the Renaissance was anti-religious. It was not; most humanists were devout and simply added new emphasis on human potential and classical learning. Mistake: assuming the printing press caused the Renaissance; the movement was already underway, and the press accelerated and spread it. Mistake: treating the Renaissance as purely artistic, when it was equally a revolution in scholarship, politics, and education. Exit ticket: (a) Give the rough time span of the Renaissance. (b) Name the technology that spread its ideas and roughly when it appeared. Answers: about 1400 to 1600; the movable-type printing press, developed by Gutenberg around 1440."}]}'::jsonb, null, 13),
  (3, 'The Protestant and Catholic Reformations', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Explain why the Protestant Reformation began, what Luther and Calvin taught, how rulers used the split for political ends, and how the Catholic Church responded. You will connect the religious divide to more than a century of conflict ending in 1648. Warm-up from the diagnostic: in what year did Luther post his 95 Theses? If you recall 1517, you have the starting gun of this story; now you will see what it set off across the whole continent, from German princes to the Council of Trent to the battlefields of central Europe."},{"heading":"The idea","text":"The Reformation was a religious movement that broke the unity of western Christianity. Martin Luther, a German monk, argued that salvation came through faith alone, by God''s grace, not by purchasing indulgences or performing works. He insisted that scripture, not church tradition or the pope, was the final authority, and he wanted ordinary people to read the Bible in their own language. These ideas, printed and spread quickly, produced new Protestant churches. John Calvin went further, teaching predestination, the belief that God had already chosen who would be saved, and built a disciplined Christian community in Geneva. Catholicism answered with its own reform, often called the Counter-Reformation, which corrected abuses while firmly reasserting traditional doctrine and papal authority. Religion and politics were inseparable: a ruler''s choice of faith reshaped law, land, and loyalty."},{"heading":"Key events and causes","text":"Causes ran deep: corruption such as the sale of indulgences, resentment of a wealthy and distant church, and humanist calls to return to original scripture. In 1517 Luther''s 95 Theses attacked indulgences; in 1521 the Diet of Worms declared him an outlaw, yet German princes protected him, partly to resist the emperor. Calvin''s Institutes of the Christian Religion appeared in 1536. In England, Henry VIII broke with Rome through the 1534 Act of Supremacy, mainly over his desire for an annulment. The Catholic response came at the Council of Trent, 1545 to 1563, which reaffirmed doctrine and reformed clergy, while the Jesuits, founded by Ignatius Loyola in 1540, taught and evangelized. The 1555 Peace of Augsburg let German princes choose Lutheranism or Catholicism for their lands. Tensions finally exploded in the Thirty Years War, 1618 to 1648, ended by the Peace of Westphalia."},{"heading":"Your turn","text":"1) What did Luther mean by salvation through faith alone? 2) Where did Calvin build his reformed community? 3) Why did some German princes support Luther? 4) What did the Council of Trent accomplish? 5) What principle did the Peace of Augsburg establish? Answers: 1) That people are saved by faith and God''s grace, not by buying indulgences or doing works. 2) Geneva. 3) Religious conviction combined with political motives, including resistance to the Holy Roman Emperor and a chance to seize church lands. 4) It reaffirmed Catholic doctrine and reformed abuses, anchoring the Counter-Reformation. 5) That each German prince could choose Lutheranism or Catholicism for his own territory."},{"heading":"Common mistakes and exit ticket","text":"Mistake: thinking the Reformation was only about theology. Politics, money, and the ambitions of princes and kings were woven through it. Mistake: confusing the Catholic Reformation with mere reaction; it both corrected abuses and defended tradition. Mistake: assuming the Thirty Years War was purely religious; by its end it was also a power struggle, with Catholic France fighting Catholic Habsburgs. Exit ticket: (a) Name the two reformers central to this lesson and one teaching of each. (b) What treaty ended the Thirty Years War, and in what year? Answers: Luther, faith alone; Calvin, predestination; the Peace of Westphalia, in 1648."}]}'::jsonb, null, 14),
  (4, 'Exploration, commerce, and the struggle over royal power', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Explain why Europeans launched voyages of exploration, what the commercial revolution changed about the economy, and how two models of government, absolutism and constitutionalism, clashed in the 1600s. You will compare Louis XIV''s France with England after its civil war and Glorious Revolution. Warm-up from the diagnostic: which monarch is the textbook model of absolutism? If you said Louis XIV, keep him in mind, because the second half of this lesson sets his version of royal power directly against the very different path England took."},{"heading":"The idea","text":"From the late 1400s, Portugal and Spain sent ships seeking sea routes to Asian spices and gold, driven by profit, religious zeal, and national rivalry. These voyages linked continents and triggered the Columbian Exchange, the transfer of crops, animals, people, and diseases across the Atlantic. The resulting commercial revolution expanded trade, banking, and joint-stock companies and fueled mercantilism, the policy of maximizing exports and bullion to strengthen the state. Wealth and war pushed rulers to centralize power. Absolutism concentrated authority in a monarch who claimed to rule by divine right, answerable to God alone. Constitutionalism instead limited the ruler through law and a representative body such as Parliament. The seventeenth century became a contest between these two visions of sovereignty."},{"heading":"Key events and causes","text":"Portuguese captains rounded Africa, and Vasco da Gama reached India in 1498; Columbus crossed the Atlantic in 1492; Magellan''s expedition circled the globe from 1519 to 1522. Floods of American silver caused a long price revolution, and chartered firms like the Dutch East India Company, founded in 1602, pioneered global commerce. In France, Louis XIV, ruling from 1643 to 1715, built Versailles, tamed the nobility, and revoked the Edict of Nantes in 1685, embodying absolutism. England moved the other way. Conflict between king and Parliament produced the English Civil War, 1642 to 1651; Charles I was executed in 1649. After the monarchy''s restoration in 1660, the Glorious Revolution of 1688 replaced James II with William and Mary, and the English Bill of Rights of 1689 made the crown subject to Parliament and law."},{"heading":"Your turn","text":"1) Name two motives behind the voyages of exploration. 2) What was the Columbian Exchange? 3) Define mercantilism in a sentence. 4) How did Louis XIV display absolutism? 5) What did the English Bill of Rights of 1689 establish? Answers: 1) Any two of profit from trade, spreading Christianity, and national or royal rivalry. 2) The transfer of crops, animals, people, and diseases between the Americas and the rest of the world. 3) A policy of boosting exports and hoarding bullion to make the state richer and stronger. 4) By centralizing power at Versailles, controlling the nobility, and revoking the Edict of Nantes. 5) That the monarch was bound by law and Parliament, limiting royal power."},{"heading":"Common mistakes and exit ticket","text":"Mistake: calling exploration purely scientific; it was driven mainly by trade, religion, and competition between crowns. Mistake: treating absolutism as total control. Even Louis XIV depended on nobles, officials, and finance. Mistake: thinking the Glorious Revolution was violent like the civil war; it was comparatively bloodless, which is why it earned its name. Exit ticket: (a) Contrast absolutism and constitutionalism in one sentence each. (b) Which year marks the Glorious Revolution? Answers: absolutism concentrates power in a monarch ruling by divine right; constitutionalism limits the ruler through law and a representative body; the Glorious Revolution occurred in 1688."}]}'::jsonb, null, 14),
  (5, 'Checkpoint 1: Renaissance to 1700', 'quiz', '{"questions":[{"prompt":"The humanist program of study was built chiefly on...","options":["medieval scholastic logic","classical Greek and Roman texts","Protestant theology","Arabic mathematics"],"answer":1,"explanation":"Humanism, the heart of the Renaissance, revived the study of ancient Greek and Roman writing."},{"prompt":"Which reformer taught the doctrine of predestination and led the church in Geneva?","options":["Martin Luther","Erasmus","John Calvin","Ignatius Loyola"],"answer":2,"explanation":"Calvin taught that God had already chosen the saved, and he built a disciplined community in Geneva."},{"prompt":"The Council of Trent (1545-1563) was the central event of the...","options":["Protestant Reformation","Catholic Counter-Reformation","Scientific Revolution","Enlightenment"],"answer":1,"explanation":"Trent reaffirmed Catholic doctrine and reformed abuses, anchoring the Catholic response to Protestantism."},{"prompt":"The Columbian Exchange refers to the transfer across the Atlantic of...","options":["gold and silver only","crops, animals, people, and diseases","printed books","classical manuscripts"],"answer":1,"explanation":"It names the two-way movement of plants, animals, people, and pathogens after 1492."},{"prompt":"Louis XIV of France is the leading example of which form of government?","options":["constitutional monarchy","republic","absolutism","parliamentary democracy"],"answer":2,"explanation":"He centralized power at Versailles and claimed to rule by divine right, the model of absolutism."},{"prompt":"The Glorious Revolution of 1688 and the Bill of Rights of 1689 in England established that...","options":["the king ruled by divine right alone","the monarch was bound by law and Parliament","Catholicism was the state religion","Parliament was abolished"],"answer":1,"explanation":"They made the crown subject to law and Parliament, cementing constitutionalism."},{"prompt":"The Peace of Westphalia in 1648 ended which long conflict?","options":["the English Civil War","the Thirty Years War","the French Wars of Religion","the Hundred Years War"],"answer":1,"explanation":"Westphalia ended the Thirty Years War (1618-1648) and reshaped European sovereignty."}]}'::jsonb, null, 8),
  (6, 'The Scientific Revolution and the Enlightenment', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Explain how the Scientific Revolution changed the way Europeans understood nature, and how Enlightenment thinkers applied reason to government, society, and religion. You will connect the two movements and name the thinkers whose ideas later fed revolutions. Warm-up from the diagnostic: who argued that the earth orbits the sun? If you named Copernicus, you have the opening move of this lesson. From that single reordering of the heavens grew a new confidence that human reason could uncover the laws of the whole world."},{"heading":"The idea","text":"The Scientific Revolution, roughly 1543 to 1700, replaced reliance on ancient authority with observation, experiment, and mathematics. Thinkers argued that nature follows discoverable laws. Francis Bacon championed inductive, evidence-based inquiry, while Rene Descartes stressed systematic doubt and reason; together they shaped the scientific method. The Enlightenment of the 1700s took this faith in reason and turned it on human affairs. If natural laws governed the stars, perhaps rational laws could govern politics and society. Enlightenment thinkers, called philosophes, argued for natural rights, religious toleration, free inquiry, and government that served the governed. Their writings circulated in salons, coffeehouses, and the famous Encyclopedie, and they inspired reformers, rulers, and eventually revolutionaries on both sides of the Atlantic."},{"heading":"Key events and causes","text":"The spark was Nicolaus Copernicus, whose 1543 book placed the sun at the center. Johannes Kepler worked out the laws of planetary motion, and Galileo Galilei used the telescope after 1609 to confirm the new astronomy, for which the church condemned him in 1633. In 1687 Isaac Newton''s Principia united the heavens and earth under the law of universal gravitation, the crowning achievement of the age. These successes convinced Enlightenment writers that reason could reform everything. John Locke argued in 1689 that people have natural rights to life, liberty, and property and may replace a government that violates them. Montesquieu urged separation of powers in 1748. Voltaire attacked intolerance, and Rousseau''s Social Contract of 1762 proposed government by the general will. Some rulers, called enlightened absolutists, adopted reforms from above."},{"heading":"Your turn","text":"1) What replaced reliance on ancient authority during the Scientific Revolution? 2) What did Newton''s Principia accomplish? 3) How is the Enlightenment connected to the Scientific Revolution? 4) What natural rights did Locke name? 5) What idea did Montesquieu contribute to government? Answers: 1) Observation, experiment, and mathematics, forming the scientific method. 2) It united the motion of the heavens and earth under one law of universal gravitation. 3) Enlightenment thinkers applied the same confidence in reason and natural law to human society and politics. 4) Life, liberty, and property. 5) The separation of powers into distinct branches of government to prevent tyranny."},{"heading":"Common mistakes and exit ticket","text":"Mistake: thinking the Scientific Revolution rejected religion outright. Most of its figures, including Newton, were believers who saw themselves uncovering God''s orderly creation. Mistake: treating the Enlightenment as a single viewpoint; thinkers disagreed sharply, for example Rousseau versus Voltaire. Mistake: assuming enlightened absolutists wanted democracy; they adopted reforms while keeping firm royal control. Exit ticket: (a) Name the thinker whose 1687 work unified heaven and earth under one law. (b) Name one Enlightenment thinker and an idea he championed. Answers: Isaac Newton; for example Locke and natural rights, Montesquieu and separation of powers, or Rousseau and the general will."}]}'::jsonb, null, 14),
  (7, 'The French Revolution and Napoleon', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Explain why the French Revolution broke out in 1789, trace its course from reform to terror, and describe how Napoleon rose, ruled, and fell. You will connect Enlightenment ideas to revolutionary demands and see how the revolution reshaped Europe. Warm-up from the diagnostic: what July 1789 event symbolizes the revolution''s start? If you said the storming of the Bastille, hold onto it. In this lesson you will watch how a financial crisis and Enlightenment ideals combined to topple one of Europe''s oldest monarchies in just a few years."},{"heading":"The idea","text":"The French Revolution overturned the old order of absolute monarchy, legal privilege, and a society divided into estates. Enlightenment ideas about natural rights, popular sovereignty, and equality before the law gave revolutionaries their language and goals. The revolution attacked the privileges of the clergy and nobility, abolished feudal dues, and proclaimed that sovereignty belonged to the nation, not the king. But revolution also unleashed fear and violence as factions fought over how far change should go and how to defend it from foreign and domestic enemies. Out of the chaos rose Napoleon Bonaparte, a brilliant general who restored order, spread many revolutionary reforms across Europe through conquest, and then crowned himself emperor, ending the republic even as he carried its legal ideas abroad."},{"heading":"Key events and causes","text":"Causes converged: a bankrupt state, heavy taxes falling on commoners, famine, and resentment of privilege, all framed by Enlightenment ideals. In 1789 the Estates-General met, the Third Estate formed a National Assembly, and a Paris crowd stormed the Bastille on July 14. The Declaration of the Rights of Man proclaimed liberty and equality, and feudalism was abolished. The monarchy fell; Louis XVI was executed in January 1793. The radical Reign of Terror, 1793 to 1794, led by Robespierre and the Committee of Public Safety, sent thousands to the guillotine until Robespierre himself fell in July 1794. The weak Directory followed until Napoleon seized power in a coup in 1799. He issued the Napoleonic Code in 1804, became emperor, dominated Europe, failed catastrophically in Russia in 1812, and was finally defeated at Waterloo in 1815. The Congress of Vienna then restored order."},{"heading":"Your turn","text":"1) Name two causes of the French Revolution. 2) What did the Declaration of the Rights of Man proclaim? 3) What was the Reign of Terror? 4) How did Napoleon first come to power? 5) What was significant about the Napoleonic Code? Answers: 1) Any two of state bankruptcy, unfair taxes, famine, resentment of privilege, and Enlightenment ideals. 2) Liberty, equality, and natural rights belonging to all citizens. 3) A radical phase, 1793 to 1794, when Robespierre''s government executed thousands of suspected enemies. 4) Through a military coup in 1799 that ended the Directory. 5) It unified and modernized law around equality before the law and property rights, and it spread across Europe."},{"heading":"Common mistakes and exit ticket","text":"Mistake: thinking the revolution instantly created democracy. It swung from reform to terror to dictatorship within a decade. Mistake: assuming Napoleon rejected the revolution; he kept many of its legal reforms while abandoning the republic for empire. Mistake: confusing the storming of the Bastille with the end of the monarchy; the king was not executed until 1793. Exit ticket: (a) Give the year the revolution began and the year Louis XVI was executed. (b) Where and in what year was Napoleon finally defeated? Answers: 1789 and 1793; Waterloo, in 1815."}]}'::jsonb, null, 15),
  (8, 'Industry, society, and the age of nationalism', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Explain why the Industrial Revolution began in Britain, how it transformed work and society, and how nationalism drove the unifications of Italy and Germany. You will link economic change to new political movements. Warm-up from the diagnostic: who engineered German unification in 1871? If you said Bismarck, you have the lesson''s second half. First, though, you will see how steam, factories, and railways remade daily life and created the working and middle classes whose demands shaped the politics that followed."},{"heading":"The idea","text":"The Industrial Revolution was the shift from hand production in homes to machine production in factories, beginning in Britain in the late 1700s. Coal, steam power, and new machines in textiles raised output enormously. Factories drew workers into fast-growing cities, creating an industrial working class and a rising middle class of owners and professionals. The change brought wealth but also crowded slums, long hours, and child labor, which sparked reform movements, trade unions, and new ideologies: liberalism favoring free markets and rights, and socialism demanding a fairer share for workers. Meanwhile nationalism, the belief that people sharing language and culture should form their own state, reshaped the map. It inspired Italians and Germans, long divided into many states, to unify into single nations by 1871."},{"heading":"Key events and causes","text":"Britain led because of coal, capital, colonies, stable government, and inventions. James Watt''s improved steam engine, patented in the 1760s, powered mills and, later, the railways that boomed after the Liverpool-Manchester line opened in 1830. Industrial misery fed reform and radical thought; Marx and Engels published The Communist Manifesto in 1848, a year of revolutions across Europe. Nationalism then drove unification. In Italy, Count Cavour of Piedmont used diplomacy while Giuseppe Garibaldi''s volunteers conquered the south, and the Kingdom of Italy was proclaimed in 1861, with Rome added in 1870. In the German lands, Otto von Bismarck of Prussia pursued unity through blood and iron, winning wars against Denmark in 1864, Austria in 1866, and France in 1870 to 1871. The German Empire was proclaimed at Versailles in January 1871."},{"heading":"Your turn","text":"1) Why did the Industrial Revolution begin in Britain? 2) Name two social effects of industrialization. 3) What is nationalism? 4) Who were the key figures in Italian unification? 5) What strategy did Bismarck use to unify Germany? Answers: 1) It had coal, capital, colonies, stable government, and a wave of useful inventions. 2) Any two of urbanization, a new working class, slums, long hours, child labor, unions, and reform movements. 3) The belief that people sharing a language and culture should have their own nation-state. 4) Cavour of Piedmont and Garibaldi, who led volunteer forces in the south. 5) A policy of blood and iron, using diplomacy and a series of wars, culminating in 1871."},{"heading":"Common mistakes and exit ticket","text":"Mistake: thinking industrialization helped everyone equally; early workers often faced dangerous, low-paid labor even as output soared. Mistake: dating German unification to the wrong war; it was sealed by the Franco-Prussian War of 1870 to 1871. Mistake: treating nationalism as always unifying; it could also tear multiethnic empires apart, a tension that fed later conflict. Exit ticket: (a) Name the power source and one industry at the heart of early industrialization. (b) Give the year both Italy and Germany completed unification as kingdoms or empires. Answers: steam power and the textile industry; Italy as a kingdom in 1861 with Rome in 1870, and the German Empire in 1871."}]}'::jsonb, null, 14),
  (9, 'Imperialism, world war, and a divided continent', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Explain the new imperialism of the late 1800s, the causes and shape of the two world wars, the Holocaust, and how the Cold War, decolonization, and European integration reshaped the continent after 1945. This is the longest sweep in the course. Warm-up from the diagnostic: in what year did World War II begin in Europe? If you said 1939, you have one anchor; by the end you will be able to place imperialism, both world wars, and the birth of the European Union on a single timeline."},{"heading":"The idea","text":"From the 1870s, industrial powers raced to seize colonies, especially in Africa and Asia, driven by demand for markets and raw materials, strategic rivalry, and the false belief in a civilizing mission. This competition, together with alliances, militarism, and nationalism, helped ignite World War I in 1914, a devastating stalemate of trenches. Its harsh settlement, economic crisis, and extremist movements led to World War II, an even deadlier conflict, during which Nazi Germany carried out the Holocaust, the systematic murder of about six million Jews and millions of others. After 1945 Europe lay divided between a Soviet-led east and a United States-led west in the Cold War, while overseas empires collapsed in a wave of decolonization. To rebuild and prevent new wars, western European states chose cooperation, leading step by step to the European Union."},{"heading":"Key events and causes","text":"The Berlin Conference of 1884 to 1885 regulated the scramble for Africa. Rising tensions exploded when the assassination of Archduke Franz Ferdinand at Sarajevo on June 28, 1914 triggered World War I, which ended with the armistice of November 11, 1918 and the Treaty of Versailles in 1919. Economic collapse in the Great Depression after 1929 helped fascists seize power, with Hitler becoming chancellor in 1933. Germany''s invasion of Poland on September 1, 1939 began World War II; the Allied landings on D-Day, June 6, 1944, preceded victory in Europe on May 8, 1945. The postwar order brought the Marshall Plan in 1948, NATO in 1949, and the Berlin Wall in 1961. Integration advanced through the 1957 Treaty of Rome and the 1992 Maastricht Treaty, which created the European Union. The Berlin Wall fell in 1989 and the Soviet Union dissolved in 1991."},{"heading":"Your turn","text":"1) Name two motives behind the new imperialism. 2) What event in 1914 triggered World War I? 3) What was the Holocaust? 4) Name two institutions of the postwar Western order. 5) Which 1992 treaty created the European Union? Answers: 1) Any two of markets and raw materials, strategic rivalry, national prestige, and the so-called civilizing mission. 2) The assassination of Archduke Franz Ferdinand at Sarajevo on June 28, 1914, amid alliances and rising tensions. 3) The systematic Nazi murder of about six million Jews and millions of other victims. 4) Any two of the Marshall Plan, NATO, and the European Economic Community. 5) The Maastricht Treaty of 1992."},{"heading":"Common mistakes and exit ticket","text":"Mistake: blaming World War I on a single cause; the assassination was the trigger, but alliances, militarism, imperial rivalry, and nationalism were the deeper causes. Mistake: confusing the dates of the two wars; World War I ran 1914 to 1918, World War II in Europe 1939 to 1945. Mistake: treating the European Union as sudden; it grew through decades of steps from coal and steel cooperation to Maastricht. Exit ticket: (a) Give the years of both world wars. (b) Name the 1989 event and the 1991 event that ended the Cold War era. Answers: 1914 to 1918 and 1939 to 1945; the fall of the Berlin Wall in 1989 and the dissolution of the Soviet Union in 1991."}]}'::jsonb, null, 15),
  (10, 'Checkpoint 2: Enlightenment to the present', 'quiz', '{"questions":[{"prompt":"Isaac Newton''s Principia (1687) is famous for...","options":["proving the earth is flat","uniting heaven and earth under universal gravitation","founding the Catholic Reformation","inventing the steam engine"],"answer":1,"explanation":"Newton showed that one law of gravitation governs both falling objects and orbiting planets."},{"prompt":"Which Enlightenment thinker argued for the separation of powers in government?","options":["Voltaire","Montesquieu","Rousseau","Descartes"],"answer":1,"explanation":"Montesquieu''s The Spirit of the Laws (1748) urged dividing power among branches to prevent tyranny."},{"prompt":"The Reign of Terror during the French Revolution was led chiefly by...","options":["Napoleon Bonaparte","Louis XVI","Maximilien Robespierre","Count Cavour"],"answer":2,"explanation":"Robespierre and the Committee of Public Safety directed the Terror of 1793-1794."},{"prompt":"The Industrial Revolution began in which country?","options":["France","Germany","Britain","Russia"],"answer":2,"explanation":"Britain''s coal, capital, and inventions made it the birthplace of industrialization in the late 1700s."},{"prompt":"German unification was completed in 1871 following a war against...","options":["Russia","Britain","France","the Ottoman Empire"],"answer":2,"explanation":"The Franco-Prussian War of 1870-1871 sealed unification, proclaimed at Versailles in January 1871."},{"prompt":"The immediate trigger of World War I in 1914 was the assassination of...","options":["Archduke Franz Ferdinand","Tsar Nicholas II","Otto von Bismarck","Adolf Hitler"],"answer":0,"explanation":"The killing of Franz Ferdinand at Sarajevo set off the alliance system and began the war."},{"prompt":"The European Union was created by which 1992 agreement?","options":["the Treaty of Versailles","the Marshall Plan","the Maastricht Treaty","the Peace of Westphalia"],"answer":2,"explanation":"The Maastricht Treaty of 1992 established the European Union, deepening decades of integration."}]}'::jsonb, null, 8)
) as v(pos, title, kind, body, notes, mins)
where not exists (
  select 1 from public.lessons l
  where l.course_id = 'bbbb0005-0000-4000-8000-000000000005' and l.position = v.pos
);
